package com.example.starter.token;

/**
 * 刷新令牌生命周期状态。
 */
public enum TokenStatus {

    /** 可用于轮换。 */
    ACTIVE,

    /** 已被成功轮换消费，不可再次使用；同键重放除外。 */
    CONSUMED,

    /** 因登出或重放检测随令牌族被撤销。 */
    REVOKED,

    /** 已达到到期时间（now &gt;= expiresAt）。 */
    EXPIRED
}

package com.example.starter.token;

/**
 * 令牌族（会话）状态。
 */
public enum FamilyStatus {

    /** 族内允许正常轮换。 */
    ACTIVE,

    /** 已终态撤销（登出或检测到重放攻击），族内任何令牌都不得再轮换。 */
    REVOKED
}

package com.example.starter.token;

/**
 * 安全事件类型。
 */
public enum SecurityEventType {

    /** 检测到已消费令牌以不同请求键再次使用，触发全族撤销。每个族仅记录一条。 */
    REPLAY_DETECTED,

    /** 主动登出撤销整个令牌族。每个族仅记录一条。 */
    LOGOUT
}

package com.example.starter.token;

import java.time.Instant;

/**
 * 令牌族（一次会话）。数据库中仅保存族级状态，不落任何令牌明文。
 *
 * @param id           族 ID（合成 UUID）
 * @param userId       合成用户标识
 * @param status       族状态
 * @param createdAt    创建时间（UTC）
 * @param revokedAt    撤销时间（UTC），未撤销时为 null
 * @param revokeReason 撤销原因（LOGOUT / REPLAY_DETECTED），未撤销时为 null
 */
public record TokenFamily(
        String id,
        String userId,
        FamilyStatus status,
        Instant createdAt,
        Instant revokedAt,
        String revokeReason) {
}

