package com.example.starter.token.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 创建会话请求；用户与客户端均为合成输入。
 *
 * @param userId   合成用户标识
 * @param clientId 合成客户端标识
 */
public record CreateSessionRequest(
        @NotBlank @Size(max = 128) String userId,
        @NotBlank @Size(max = 128) String clientId) {
}

package com.example.starter.token.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 轮换请求。
 *
 * @param requestId    请求键：同一请求键的安全重试必须返回首次派生出的子令牌
 * @param refreshToken 当前明文刷新令牌
 * @param clientId     合成客户端标识
 */
public record RotateRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 1024) String refreshToken,
        @NotBlank @Size(max = 128) String clientId) {
}

package com.example.starter.token.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 登出请求；撤销整个令牌族。
 *
 * @param refreshToken 族内任意明文刷新令牌
 * @param clientId     合成客户端标识
 */
public record LogoutRequest(
        @NotBlank @Size(max = 1024) String refreshToken,
        @NotBlank @Size(max = 128) String clientId) {
}

package com.example.starter.token.api;

import java.time.Instant;

/**
 * 会话创建/轮换成功响应。
 *
 * @param familyId       令牌族 ID
 * @param refreshToken   明文刷新令牌（仅此一次返回，数据库不落明文）
 * @param expiresAt      到期时间（UTC）
 * @param replayed       true 表示本次为同请求键的安全重试，返回的是首次派生的子令牌
 */
public record TokenIssuedResponse(
        String familyId,
        String refreshToken,
        Instant expiresAt,
        boolean replayed) {
}

package com.example.starter.token.api;

import java.time.Instant;

/**
 * 安全事件视图。
 *
 * @param id        事件 ID
 * @param eventType 事件类型（REPLAY_DETECTED / LOGOUT）
 * @param familyId  相关令牌族 ID
 * @param requestId 触达事件的请求键，可能为 null
 * @param detail    补充说明
 * @param createdAt 事件时间（UTC）
 */
public record SecurityEventResponse(
        Long id,
        String eventType,
        String familyId,
        String requestId,
        String detail,
        Instant createdAt) {
}

package com.example.starter.token;

/**
 * 请求被拒绝的业务异常，由控制器映射为对应的 HTTP 4xx 状态码。
 */
public class TokenServiceException extends RuntimeException {

    /** 建议的 HTTP 状态码。 */
    private final int status;

    public TokenServiceException(int status, String message) {
        super(message);
        this.status = status;
    }

    public int status() {
        return status;
    }
}

