                token.seq(),
                token.status().name(),
                token.clientId(),
                Timestamp.from(token.issuedAt()),
                Timestamp.from(token.expiresAt()),
                token.consumedAt() == null ? null : Timestamp.from(token.consumedAt()));
    }

